	private void testConstantAggregatesByGroup(RepositoryConnection conn) {
		String query = "SELECT ?x (COUNT(1) AS ?c) (SUM(5) AS ?s) "
				+ "{ VALUES ?x { 1 1 2 } } GROUP BY ?x ORDER BY ?x";

		try (TupleQueryResult result = conn.prepareTupleQuery(query).evaluate()) {
			assertThat(result.hasNext()).isTrue();
			BindingSet firstGroup = result.next();
			assertThat(firstGroup.getValue("x")).isEqualTo(literal("1", CoreDatatype.XSD.INTEGER));
			assertThat(firstGroup.getValue("c")).isEqualTo(literal("2", CoreDatatype.XSD.INTEGER));
			assertThat(firstGroup.getValue("s")).isEqualTo(literal("10", CoreDatatype.XSD.INTEGER));

			assertThat(result.hasNext()).isTrue();
			BindingSet secondGroup = result.next();
			assertThat(secondGroup.getValue("x")).isEqualTo(literal("2", CoreDatatype.XSD.INTEGER));
			assertThat(secondGroup.getValue("c")).isEqualTo(literal("1", CoreDatatype.XSD.INTEGER));
			assertThat(secondGroup.getValue("s")).isEqualTo(literal("5", CoreDatatype.XSD.INTEGER));
			assertThat(result.hasNext()).isFalse();
		}
	}

